 function diasAtras(ddmm){var m=/^(\d{1,2})\/(\d{1,2})(?:\/\d{2,4})?$/.exec(String(ddmm==null?'':ddmm).trim());if(!m||!hoje)return Infinity;var best=Infinity;[-1,0,1].forEach(function(k){var dif=Math.round((hoje-new Date(hoje.getFullYear()+k,+m[2]-1,+m[1]))/864e5);if(Math.abs(dif)<Math.abs(best))best=dif});return Math.max(0,best)}
