.ap-votos{text-align:right;white-space:nowrap}
.ap-pct{font-size:1.2rem;font-weight:800;display:block;line-height:1.1}
.ap-abs{font-size:.76rem;color:var(--ap-suave)}
.ap-totais{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;
  margin-top:20px;padding-top:16px;border-top:1px solid var(--ap-borda)}
.ap-totais div{display:flex;flex-direction:column;gap:2px}
.ap-totais span{font-size:.7rem;text-transform:uppercase;letter-spacing:.04em;color:var(--ap-suave);font-weight:700}
.ap-totais strong{font-size:1.05rem}
.ap-tabela{width:100%;border-collapse:collapse;font-size:.92rem}
.ap-tabela th{text-align:left;font-size:.7rem;text-transform:uppercase;letter-spacing:.04em;
  color:var(--ap-suave);padding:8px 10px;border-bottom:2px solid var(--ap-borda)}
.ap-tabela td{padding:11px 10px;border-bottom:1px solid var(--ap-borda);vertical-align:middle}
.ap-tabela tr:nth-child(even) td{background:var(--ap-alt)}
.ap-uf-sigla{font-weight:800;color:var(--ap-verde)}
.ap-tabela .ap-lid{font-weight:700}
.ap-mini{font-size:.76rem;color:var(--ap-suave)}
.ap-rolagem{overflow-x:auto}
.ap-fonte{font-size:.8rem;color:var(--ap-suave);margin-top:20px;line-height:1.5}
.ap-aviso{padding:26px;border:2px dashed var(--ap-borda);border-radius:14px;text-align:center;
  color:var(--ap-suave);line-height:1.6}
.ap-aviso b{display:block;font-size:1.15rem;color:var(--ap-texto);margin-bottom:6px}
.ap-mais{margin-top:14px;text-align:center}
.ap-mais button{background:none;border:1px solid var(--ap-borda);border-radius:8px;padding:9px 20px;
  font-weight:700;cursor:pointer;color:var(--ap-texto);font-size:.88rem;font-family:inherit}
html[data-theme="dark"] #hmt-apuracao,body.dark-mode #hmt-apuracao{
  --ap-fundo:#161b18;--ap-borda:#2b332e;--ap-texto:#eef3f0;--ap-suave:#9fb0a6;--ap-alt:#1c2320}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-apuracao{
  --ap-fundo:#161b18;--ap-borda:#2b332e;--ap-texto:#eef3f0;--ap-suave:#9fb0a6;--ap-alt:#1c2320}}
@media (max-width:600px){
  .ap-destaque{grid-template-columns:1fr}
  .ap-cand{grid-template-columns:40px 1fr;row-gap:6px}
  .ap-votos{grid-column:1/-1;text-align:left;display:flex;align-items:baseline;gap:10px}
  .ap-filtros{width:100%}.ap-filtros label{flex:1 1 45%}.ap-filtros select{min-width:0;width:100%}
}
