<script>
(function () {
  // ?demo=1 abre a demonstração com os resultados oficiais de 2022
  var DEMO = /[?&]demo=1/.test(location.search);
  var BASE = "/content/media/apuracao/" + (DEMO ? "demo/" : "");
  var UFS = {br:"Brasil",ac:"Acre",al:"Alagoas",am:"Amazonas",ap:"Amapá",ba:"Bahia",ce:"Ceará",
    df:"Distrito Federal",es:"Espírito Santo",go:"Goiás",ma:"Maranhão",mg:"Minas Gerais",
    ms:"Mato Grosso do Sul",mt:"Mato Grosso",pa:"Pará",pb:"Paraíba",pe:"Pernambuco",pi:"Piauí",
    pr:"Paraná",rj:"Rio de Janeiro",rn:"Rio Grande do Norte",ro:"Rondônia",rr:"Roraima",
    rs:"Rio Grande do Sul",sc:"Santa Catarina",se:"Sergipe",sp:"São Paulo",to:"Tocantins",zz:"Exterior"};
  var indice = null, mostrarTodos = false, aba = "resultado", muniCache = {};
  var $ = function (id) { return document.getElementById(id); };
  var pega = function (u) {
    return fetch(BASE + u + "?t=" + Date.now())
      .then(function (r) { return r.ok ? r.json() : null; }).catch(function () { return null; });
  };
  function num(v) { var n = parseInt(v, 10); return isNaN(n) ? "—" : n.toLocaleString("pt-BR"); }
  function pctNum(v) { return parseFloat(String(v || "0").replace(",", ".")) || 0; }
  function eleito(c) { return c.e === "s" || /^eleito/i.test(c.st || ""); }
  function segundoTurno(c) { return /2.*turno/i.test(c.st || ""); }
  function selo(c) {
    if (eleito(c)) return '<span class="ap-tag">Eleito</span>';
    if (segundoTurno(c)) return '<span class="ap-tag segundo">2º turno</span>';
    return "";
  }
  function aviso(titulo, texto) {
    $("ap-lista").innerHTML = '<div class="ap-aviso"><b>' + titulo + "</b>" + texto + "</div>";
    $("ap-destaque").innerHTML = "";
    $("ap-progresso").hidden = true; $("ap-totais").hidden = true;
  }

  function trocarAba(nova) {
    aba = nova;
    Array.prototype.forEach.call(document.querySelectorAll(".ap-aba"), function (b) {
      b.classList.toggle("ativa", b.dataset.aba === nova);
    });
    $("ap-painel-resultado").hidden = nova !== "resultado";
    $("ap-painel-placar").hidden = nova !== "placar";
    $("ap-painel-gastos").hidden = nova !== "gastos";
    if (nova === "placar") renderPlacar();
    if (nova === "gastos") renderGastos();
  }

  function filtrosPrevistos() {
    // fora da janela de apuração: seletores testáveis com os cargos e UFs
    // previstos da Eleição Geral (trocados pelos reais quando o TSE liberar)
    if ($("ap-cargo").options.length) return;
    var cargos = {"0001": "Presidente", "0003": "Governador",
                  "0005": "Senador", "0006": "Deputado Federal",
                  "0007": "Deputado Estadual", "0008": "Deputado Distrital"};
    $("ap-cargo").innerHTML = Object.keys(cargos).map(function (c) {
      return '<option value="' + c + '">' + cargos[c] + "</option>";
    }).join("");
    $("ap-cargo").value = "0003";
    $("ap-uf").innerHTML = Object.keys(UFS).map(function (u) {
      return '<option value="' + u + '">' + UFS[u] + "</option>";
    }).join("");
    $("ap-uf").value = "mt";
  }

  function montarFiltros() {
    var cargos = indice.disponivel || {}, codigos = Object.keys(cargos).sort();
    if (!codigos.length) return false;
    $("ap-cargo").innerHTML = codigos.map(function (c) {
      return '<option value="' + c + '">' + cargos[c].rotulo + "</option>";
    }).join("");
    $("ap-cargo").value = (cargos["0003"] && cargos["0003"].abr.indexOf("mt") > -1) ? "0003" : codigos[0];
    preencherUfs();
    return true;
  }

  function preencherUfs() {
    var abrs = (indice.disponivel[$("ap-cargo").value] || {}).abr || [];
    var anterior = $("ap-uf").value;
    $("ap-uf").innerHTML = abrs.map(function (u) {
      return '<option value="' + u + '">' + (UFS[u] || u.toUpperCase()) + "</option>";
    }).join("");
    if (abrs.indexOf(anterior) > -1) $("ap-uf").value = anterior;
    else if (abrs.indexOf("mt") > -1) $("ap-uf").value = "mt";
  }

  function preencherMunicipios() {
    var uf = $("ap-uf").value, cargo = $("ap-cargo").value, chave = uf + "-c" + cargo;
    var lb = $("ap-lb-mun");
    function aplicar(d) {
      if (!d || !d.municipios || !d.municipios.length) { lb.hidden = true; return atualizar(); }
      lb.hidden = false;
      $("ap-mun").innerHTML = '<option value="">Todo o estado</option>' +
        d.municipios.map(function (m) {
          return '<option value="' + m.cd + '">' + m.nm + (m.capital ? " (capital)" : "") + "</option>";
        }).join("");
      atualizar();
    }
    if (muniCache[chave] !== undefined) return aplicar(muniCache[chave]);
    pega("municipios-" + chave + ".json").then(function (d) { muniCache[chave] = d; aplicar(d); });
  }

  function renderDestaque(cands) {
    if (cands.length < 2) { $("ap-destaque").innerHTML = ""; return; }
    $("ap-destaque").innerHTML = '<div class="ap-destaque">' + cands.slice(0, 2).map(function (c, i) {
      return '<div class="ap-dcard' + (i === 0 ? " lider" : "") + '">' +
        '<div class="ap-dnum">Nº ' + (c.n || "") + selo(c) + "</div>" +
        '<div class="ap-dnome">' + (c.nm || "") + "</div>" +
        '<div class="ap-dpart">' + ((c.cc || "").split(" / ")[0]) + "</div>" +
        '<div class="ap-dpct">' + (c.pvap || "0") + "%</div>" +
        '<div class="ap-dvotos">' + num(c.vap) + " votos</div></div>";
    }).join("") + "</div>";
  }

  function render(d, titulo) {
    $("ap-progresso").hidden = false; $("ap-totais").hidden = false;
    $("ap-barra-fill").style.width = pctNum(d.secoes_totalizadas_pct) + "%";
    $("ap-pct").textContent = String(d.secoes_totalizadas_pct || "0") + "%";
    $("ap-secoes").textContent = "(" + num(d.secoes_totalizadas) + " de " + num(d.secoes) +
      " seções" + (titulo ? " — " + titulo : "") + ")";
    $("ap-comp").textContent = num(d.comparecimento) + " (" + d.comparecimento_pct + "%)";
    $("ap-abst").textContent = num(d.abstencao) + " (" + d.abstencao_pct + "%)";
    $("ap-brancos").textContent = num(d.brancos) + " (" + d.brancos_pct + "%)";
    $("ap-nulos").textContent = num(d.nulos) + " (" + d.nulos_pct + "%)";
    $("ap-atualizado").textContent = d.atualizado ? "Última atualização do TSE: " + d.atualizado : "";
    var cands = d.candidatos || [];
    renderDestaque(cands);
    var resto = cands.length > 2 ? cands.slice(2) : [];
    var limite = mostrarTodos ? resto.length : 10;
    $("ap-lista").innerHTML = resto.slice(0, limite).map(function (c) {
      return '<div class="ap-cand' + (eleito(c) ? " eleito" : "") + '" style="--pct:' + pctNum(c.pvap) + '%">' +
        '<div class="ap-num">' + (c.n || "") + "</div>" +
        '<div><div class="ap-nome">' + (c.nm || "") + selo(c) + "</div>" +
        (c.nv ? '<div class="ap-part">Vice: ' + c.nv + "</div>" : "") +
        '<div class="ap-part">' + (c.cc || "") + "</div></div>" +
        '<div class="ap-votos"><span class="ap-pct">' + (c.pvap || "0") + "%</span>" +
        '<span class="ap-abs">' + num(c.vap) + " votos</span></div></div>";
    }).join("");
    if (resto.length > 10) {
      var b = document.createElement("div");
      b.className = "ap-mais";
      b.innerHTML = "<button>" + (mostrarTodos ? "Mostrar menos" :
        "Ver todos os " + d.total_candidatos + " candidatos") + "</button>";
      b.querySelector("button").onclick = function () { mostrarTodos = !mostrarTodos; atualizar(); };
      $("ap-lista").appendChild(b);
    }
  }

  function renderPlacar() {
    var cargo = $("ap-cargo").value;
    pega("placar-c" + cargo + ".json").then(function (d) {
      if (!d || !d.estados || !d.estados.length) {
        $("ap-placar").innerHTML = '<div class="ap-aviso"><b>Placar indisponível</b>' +
          "O resumo por estado aparece para os cargos disputados em cada unidade da federação.</div>";
        return;
      }
      $("ap-placar").innerHTML = '<div class="ap-rolagem"><table class="ap-tabela"><thead><tr>' +
        "<th>Estado</th><th>Apurado</th><th>Liderança</th><th>%</th><th>2º colocado</th>" +
        "</tr></thead><tbody>" + d.estados.map(function (e) {
          return "<tr><td><span class=\"ap-uf-sigla\">" + e.uf.toUpperCase() + "</span> " +
            '<span class="ap-mini">' + (UFS[e.uf] || "") + "</span></td>" +
            "<td>" + (e.pct_apurado || "0") + "%</td>" +
            '<td><span class="ap-lid">' + (e.lider || "") + "</span> " + selo(e) +
            '<div class="ap-mini">' + (e.cc || "") + "</div></td>" +
            "<td><strong>" + (e.pvap || "0") + "%</strong></td>" +
            '<td class="ap-mini">' + (e.segundo || "—") +
            (e.segundo_pvap ? " (" + e.segundo_pvap + "%)" : "") + "</td></tr>";
        }).join("") + "</tbody></table></div>";
    });
  }

  function moeda(v) {
    var n = parseFloat(v) || 0;
    return "R$ " + n.toLocaleString("pt-BR", {minimumFractionDigits: 2, maximumFractionDigits: 2});
  }

  function renderGastos() {
    var uf = $("ap-uf").value;
    pega("gastos-" + uf + ".json").then(function (d) {
      if (!d || !d.candidatos || !d.candidatos.length) {
        $("ap-gastos").innerHTML = '<div class="ap-aviso"><b>Prestação de contas ainda não divulgada</b>' +
          "As receitas e despesas de campanha são publicadas pelo TSE durante e após a " +
          "eleição. Assim que os dados oficiais saírem, eles aparecem aqui.</div>";
        return;
      }
      $("ap-gastos").innerHTML = '<div class="ap-rolagem"><table class="ap-tabela"><thead><tr>' +
        "<th>Candidato</th><th>Cargo</th><th>Receitas</th><th>Despesas</th><th>Saldo</th>" +
        "</tr></thead><tbody>" + d.candidatos.slice(0, 60).map(function (c) {
          var saldo = (parseFloat(c.receitas) || 0) - (parseFloat(c.despesas) || 0);
          return '<tr><td><span class="ap-lid">' + (c.urna || c.nome) + "</span>" +
            '<div class="ap-mini">' + (c.partido || "") + "</div></td>" +
            '<td class="ap-mini">' + (c.cargo || "") + "</td>" +
            "<td>" + moeda(c.receitas) + "</td><td><strong>" + moeda(c.despesas) + "</strong></td>" +
            "<td>" + moeda(saldo) + "</td></tr>";
        }).join("") + "</tbody></table></div>" +
        '<p class="ap-fonte">Fonte: ' + (d.fonte || "TSE") + " — dados de " + (d.ano || "") +
        ", atualizados em " + (d.gerado || "") + ".</p>";
    });
  }

  function atualizar() {
    var uf = $("ap-uf").value, cargo = $("ap-cargo").value;
    var mun = $("ap-lb-mun").hidden ? "" : $("ap-mun").value;
    if (!uf || !cargo) return;
    var arquivo = (mun ? uf + mun : uf) + "-c" + cargo + ".json";
    pega(arquivo).then(function (d) {
      if (!d) return aviso("Sem dados para esta seleção", "Escolha outro cargo, estado ou cidade.");
      render(d, d.municipio || "");
    });
    if (aba === "placar") renderPlacar();
  }

  function ciclo() {
    pega("indice.json").then(function (idx) {
      if (!idx) return aviso("Apuração ainda não iniciada",
        "Os dados do TSE aparecerão aqui automaticamente assim que a apuração começar.");
      indice = idx;
      if (idx.status !== "apurando" || !Object.keys(idx.disponivel || {}).length) {
        $("ap-status").textContent = "Aguardando o início da apuração";
        filtrosPrevistos();
        return aviso("Apuração das Eleições 2026", idx.motivo ||
          "Aguardando a liberação dos dados pelo TSE.");
      }
      var nomeEle = ((idx.eleicao || {}).nome || "");
      $("ap-demo").hidden = nomeEle.toUpperCase().indexOf("SIMULA") === -1;
      $("ap-status").textContent = $("ap-demo").hidden ? "Apuração em tempo real"
        : "Demonstração da ferramenta";
      $("ap-btn-placar").hidden = false;
      pega("gastos-" + ($("ap-uf").value || "mt") + ".json").then(function (g) {
        $("ap-btn-gastos").hidden = !(g && g.candidatos && g.candidatos.length);
      });
      if (!$("ap-cargo").options.length) {
        if (!montarFiltros()) return;
        $("ap-cargo").onchange = function () {
          mostrarTodos = false; preencherUfs(); preencherMunicipios();
          if (aba === "placar") renderPlacar();
        };
        $("ap-uf").onchange = function () { mostrarTodos = false; preencherMunicipios(); };
        $("ap-mun").onchange = function () { mostrarTodos = false; atualizar(); };
        Array.prototype.forEach.call(document.querySelectorAll(".ap-aba"), function (b) {
          b.onclick = function () { trocarAba(b.dataset.aba); };
        });
        return preencherMunicipios();
      }
      atualizar();
    });
  }
  ciclo();
  setInterval(ciclo, 60000);
})();
</script>
